@media(max-width:760px){main{padding:0 20px}.top-inner{padding:18px 20px}.search-section{max-width:none;margin-top:22px}.branch-intro{padding-top:8px}.section-heading h2{font-size:30px}.family-panel{padding:25px 5px 30px}.grandchildren{padding-right:28px}.grandchildren .person{min-height:105px}.choose-label{padding-top:22px}.home-branches-heading{margin-top:8px}.branch-card{border-radius:50% 6% 50% 6%;padding:22px 24px}.branch-card strong{font-size:28px}.branch-card .branch-icon{font-size:26px}.branch-card small{font-size:12px}.tree-sheet-head h2{font-size:31px}.birthday-controls{grid-template-columns:1fr 145px}.grove-caption{font-size:12px}}
