@media print{.print-page svg{max-height:264mm;width:100%;height:auto}.print-page{background:var(--cream)}.birthday-print{font-family:var(--body)}.birthday-print h1{font-family:var(--display);font-size:32px}.birthday-print th,.birthday-print td{font-size:12px}.olive-person{cursor:default}}
